/** The two inks, as a pair. */
export type Ink = {
  /** Drawn on light backdrops. */
  dark: string;
  /** Drawn on dark backdrops. */
  light: string;
};

/**
 * Near-black and pure white.
 *
 * White is not `#fafafa` and black is not the theme's `--foreground`, and neither is an
 * oversight: the backdrop here is a colour the user picked, not a surface the theme owns, so the
 * ink must not flip when the theme does. A chip that reads in light mode and vanishes in dark
 * mode is the bug this whole function exists to stop.
 */
export const INK: Ink = { dark: "#000000", light: "#ffffff" };

/** `#rgb`, `#rgba`, `#rrggbb`, `#rrggbbaa`, with or without the `#`. */
const HEX = /^#?(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;

/**
 * The three channels of a hex colour as 0–1, or nothing.
 *
 * Alpha is parsed and dropped. Compositing it would need the colour *behind* the swatch, which
 * is the one thing a function taking a single colour cannot know — and guessing white would be
 * wrong in dark mode, which is where a translucent chip is hardest to read.
 */
function channels(hex: string): [number, number, number] | undefined {
  if (!HEX.test(hex)) return undefined;

  const digits = hex.replace("#", "");
  // Shorthand doubles each digit — `#f80` is `#ff8800`, not `#0f0800`. auto-cal's version slices
  // fixed offsets out of the string instead, so a three-digit colour parses as something else
  // entirely and returns an ink for a colour nobody picked.
  const full =
    digits.length <= 4
      ? digits
          .split("")
          .map((digit) => digit + digit)
          .join("")
      : digits;

  return [0, 2, 4].map((at) => Number.parseInt(full.slice(at, at + 2), 16) / 255) as [
    number,
    number,
    number,
  ];
}

/** WCAG 2.x relative luminance. The piecewise curve is the standard sRGB transfer function. */
function luminance([r, g, b]: [number, number, number]): number {
  const linear = ([r, g, b] as const).map((channel) =>
    channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4,
  ) as [number, number, number];

  return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2];
}

/** WCAG 2.x contrast between two relative luminances, 1 through 21. */
function contrast(a: number, b: number): number {
  const [lighter, darker] = a > b ? [a, b] : [b, a];
  return (lighter + 0.05) / (darker + 0.05);
}

/**
 * Ink for text sitting *on* a colour the user chose — a calendar event, a tag, a selected chip,
 * the tick on a picked swatch.
 *
 * Those places hardcode white, and white is right for about half of any palette: white on
 * `#f59e0b` is 2.2:1 and on `#14b8a6` is 2.5:1, both well under AA. Legibility cannot be baked
 * into a variant when the backdrop is a value out of the database, so it is computed per colour.
 *
 * Returns `undefined` for anything that is not a hex colour, so a caller falls back to the
 * inherited foreground rather than painting black onto a value it failed to read. That is the
 * contract worth keeping: the failure is visible, and it is visible in the right direction.
 *
 * ```tsx
 * <span style={{ background: tag.color, color: readableTextColor(tag.color) }}>{tag.name}</span>
 * ```
 *
 * Two projects wrote this independently and arrived at the same algorithm by two routes — one
 * comparing luminance against `0.179`, one comparing the two contrast ratios. They agree exactly,
 * because `0.179` *is* the crossover: `Math.sqrt(1.05 * 0.05) - 0.05`. The ratio comparison is
 * what is written here, because it needs no constant to be believed.
 */
export function readableTextColor(
  color: string | null | undefined,
  ink: Ink = INK,
): string | undefined {
  if (!color) return undefined;

  const rgb = channels(color);
  if (!rgb) return undefined;

  const backdrop = luminance(rgb);
  return contrast(backdrop, 0) >= contrast(backdrop, 1) ? ink.dark : ink.light;
}

import { describe, expect, it } from "vitest";
import { INK, readableTextColor } from "./readable-text-color";

/** A palette of user-pickable colours — the case the function exists for. */
const ACTIVITY_COLORS = [
  "#ef4444",
  "#f59e0b",
  "#eab308",
  "#84cc16",
  "#14b8a6",
  "#06b6d4",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899",
  "#64748b",
];

/**
 * WCAG 2.x luminance and contrast, written out again here so the test does not trust the module's
 * own maths. Shared by both spellings below rather than hand-rolled twice.
 */
const linear = (color: string): [number, number, number] =>
  [1, 3, 5]
    .map((at) => Number.parseInt(color.slice(at, at + 2), 16) / 255)
    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4)) as [
    number,
    number,
    number,
  ];

function luminance(hex: string) {
  const [r, g, b] = linear(hex);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function contrast(hex: string, ink: string) {
  const pair = [luminance(hex), luminance(ink)];
  return (Math.max(...pair) + 0.05) / (Math.min(...pair) + 0.05);
}

describe("readableTextColor", () => {
  it("picks the ink with more contrast, for every colour in the palette", () => {
    for (const color of ACTIVITY_COLORS) {
      const chosen = readableTextColor(color) as string;
      const other = chosen === INK.dark ? INK.light : INK.dark;
      expect(contrast(color, chosen)).toBeGreaterThanOrEqual(contrast(color, other));
    }
  });

  /**
   * The number in the survey. Hardcoded white drops to 2.2:1 on the amber swatch; picking per
   * colour never drops below AA across the palette.
   */
  it("clears AA on every colour in the palette, which hardcoded white does not", () => {
    const hardcoded = ACTIVITY_COLORS.map((c) => contrast(c, "#ffffff"));
    expect(Math.min(...hardcoded)).toBeLessThan(4.5);

    for (const color of ACTIVITY_COLORS) {
      expect(contrast(color, readableTextColor(color) as string)).toBeGreaterThanOrEqual(4.5);
    }
  });

  it("agrees with the luminance-threshold spelling of the same algorithm", () => {
    // `0.179` is `Math.sqrt(1.05 * 0.05) - 0.05` — the crossover, not an approximation of it.
    const threshold = Math.sqrt(1.05 * 0.05) - 0.05;

    for (const color of ACTIVITY_COLORS) {
      const byThreshold = luminance(color) > threshold ? INK.dark : INK.light;
      expect(readableTextColor(color)).toBe(byThreshold);
    }
  });

  it("reads shorthand hex as the colour it means", () => {
    // The bug in the fixed-offset version: `#f80` is `#ff8800`, a light amber wanting black ink,
    // not the near-black `#0f0800` that slicing byte pairs out of a four-character string yields.
    expect(readableTextColor("#f80")).toBe(readableTextColor("#ff8800"));
    expect(readableTextColor("#f80")).toBe(INK.dark);
  });

  it("takes a colour with or without the hash, and any case", () => {
    expect(readableTextColor("3B82F6")).toBe(readableTextColor("#3b82f6"));
  });

  it("ignores alpha rather than compositing against a backdrop it cannot see", () => {
    expect(readableTextColor("#ffffff00")).toBe(readableTextColor("#ffffff"));
  });

  it("returns nothing it cannot read, so the caller falls back instead of guessing", () => {
    for (const value of ["", "rebeccapurple", "rgb(0 0 0)", "#12345", "#gggggg", null, undefined]) {
      expect(readableTextColor(value)).toBeUndefined();
    }
  });

  it("takes a caller's own pair of inks", () => {
    // An app using a near-black rather than pure black should not be restyled by adopting this.
    expect(readableTextColor("#eab308", { dark: "#0b0b0f", light: "#ffffff" })).toBe("#0b0b0f");
  });
});
